#include <span>
#include <optional>
#include <functional>
#include <unordered_set>
#include <utility>
#include <vector>
#include <cassert>
#include <iostream>
using ULONGLONG=unsigned long long;
struct CItem { CItem* parent=nullptr; ULONGLONG logical=0,physical=0; CItem* GetParent() const{return parent;} ULONGLONG GetSizeLogical() const{return logical;} ULONGLONG GetSizePhysical() const{return physical;} };
struct CItemSearch {using SizeTotals=std::pair<ULONGLONG,ULONGLONG>;static std::optional<SizeTotals> CalculateTotals(std::span<CItem* const>, const std::function<bool()>& = {});};
std::optional<CItemSearch::SizeTotals> CItemSearch::CalculateTotals(const std::span<CItem* const> items,
    const std::function<bool()>& isCancelled)
{
    ULONGLONG totalLogical = 0;
    ULONGLONG totalPhysical = 0;
    const std::unordered_set<const CItem*> matches(items.begin(), items.end());

    // Count only the outermost matching items, so nested results contribute once.
    for (const auto* item : matches)
    {
        if (isCancelled && isCancelled()) return std::nullopt;
        auto* parent = item->GetParent();
        while (parent != nullptr && !matches.contains(parent)) parent = parent->GetParent();
        if (parent != nullptr) continue;
        totalLogical += item->GetSizeLogical();
        totalPhysical += item->GetSizePhysical();
    }
    return SizeTotals{ totalLogical, totalPhysical };
}
int main(){CItem n[7]; n[1].parent=n[2].parent=&n[0]; n[3].parent=n[4].parent=&n[1]; n[5].parent=n[6].parent=&n[2]; for(int i=3;i<7;++i){n[i].logical=i*11;n[i].physical=i*16;}for(int i=2;i>=0;--i){n[i].logical=n[2*i+1].logical+n[2*i+2].logical;n[i].physical=n[2*i+1].physical+n[2*i+2].physical;}int checks=0;for(int mask=0;mask<128;++mask){std::vector<CItem*> selected;for(int i=0;i<7;++i)if(mask&(1<<i)){selected.push_back(&n[i]);selected.push_back(&n[i]);}ULONGLONG l=0,p=0;for(int leaf=3;leaf<7;++leaf){bool included=false;for(int i=leaf;;i=(i-1)/2){if(mask&(1<<i))included=true;if(i==0)break;}if(included){l+=n[leaf].logical;p+=n[leaf].physical;}}auto r=CItemSearch::CalculateTotals(selected);assert(r&&r->first==l&&r->second==p);++checks;}std::vector<CItem*> all{&n[0],&n[1]};assert(!CItemSearch::CalculateTotals(all,[]{return true;}));std::cout<<checks<<" exhaustive subset totals and cancellation passed\n";}
